eline_btn": {"id": "run_pipeline_btn", "type": "ActionButton", "props": {"label": "Run Ingest & Scoring Pipeline", "icon": "play", "variant": "contained", "onClick": [{"kind": "runOperation", "operation": "mdmScoring.runPipeline", "progressVariable": "ingest_status", "params": {"universe_size": "{{vars.universe_size}}"}, "successMessage": "MDM Multi-Vendor Ingestion & Scoring pipeline completed successfully."}]}, "style": {"flex": "0 0 auto"}}, "pipeline_progress": {"id": "pipeline_progress", "type": "ProgressBar", "props": {"variable": "ingest_status", "showSignal": true, "color": "primary"}, "visibleWhen": {"type": "condition", "field": "vars.ingest_status", "operator": "is_not_null"}}, "pipeline_hud": {"id": "pipeline_hud", "type": "AlertBanner", "props": {"severity": "info", "text": "Tripartite Pipeline: Raw files \u2192 Apache Iceberg Parquet Lakehouse \u2192 Centralized Validation Engine \u2192 Staging DB \u2192 MDM Survivorship Mastering \u2192 Vendor Quality & Displacement Scoring Mart (StarRocks: mdm_analytics.vendor_substitution_daily)."}}, "matrix_search": {"id": "matrix_search", "type": "SearchInput", "props": {"variable": "matrix_search", "placeholder": "Typeahead search attribute or vendor (e.g. CLOSING_PRICE, BBG)...", "variant": "typeahead", "optionsFrom": "queries.scorecard.data.substitution_matrix", "optionsField": "attribute_code", "maxWidth": 420}}, "tier_facets": {"id": "tier_facets", "type": "FacetFilter", "props": {"variable": "tier_filter", "label": "Attribute Tier", "allLabel": "All Tiers", "facetField": "tier", "query": "scorecard", "rowsPath": "substitution_matrix", "options": [{"value": "1", "label": "Tier 1 (Core Identity & Price)", "color": "warning"}, {"value": "2", "label": "Tier 2 (Risk & Classification)", "color": "primary"}, {"value": "3", "label": "Tier 3 (Reference & Descriptive)", "color": "default"}]}}, "matrix_grid": {"id": "matrix_grid", "type": "DataGrid", "props": {"query": "scorecard", "rowsPath": "substitution_matrix", "rowKey": "vendor_id,attribute_code", "enableSearch": true, "searchVariant": "typeahead", "searchOptionsField": "attribute_code", "searchVariable": "matrix_search", "searchFields": ["attribute_code", "vendor_id", "entity_domain"], "filters": {"vendor_id": "vendor_filter", "tier": "tier_filter", "entity_domain": "entity_domain"}, "emptyText": "No scoring data matching your search or filter criteria.", "columns": [{"id": "attr", "header": "Attribute", "cell": {"kind": "twoLine", "primary": "{{row.attribute_code}}", "secondary": "Tier {{row.tier}}"}}, {"id": "domain", "header": "Domain", "cell": {"kind": "chip", "value": "{{row.entity_domain}}", "variant": "outlined"}}, {"id": "vendor", "header": "Vendor", "cell": {"kind": "chip", "value": "{{row.vendor_id}}", "variant": "outlined"}}, {"id": "tier", "header": "Tier", "cell": {"kind": "chip", "value": "{{row.tier}}", "colorMap": {"1": "warning", "2": "primary", "3": "default"}}}, {"id": "sufficiency", "header": "Substitution Rate", "cell": {"kind": "percent", "value": "{{row.sufficiency_rate_pct}}"}, "align": "right"}, {"id": "coverage", "header": "Coverage", "cell": {"kind": "percent", "value": "{{row.coverage_pct}}"}, "align": "right"}, {"id": "cond_suff", "header": "Conditional Sufficiency", "cell": {"kind": "percent", "value": "{{row.conditional_sufficiency_pct}}"}, "align": "right"}, {"id": "solo_rate", "header": "Solo Rate", "cell": {"kind": "percent", "value": "{{row.solo_rate_pct}}"}, "align": "right"}, {"id": "oer", "header": "Override Endorsement (OER)", "cell": {"kind": "percent", "value": "{{row.override_endorsement_rate_pct}}"}, "align": "right"}]}}, "frontier_grid": {"id": "frontier_grid", "type": "DataGrid", "props": {"query": "scorecard", "rowsPath": "frontier_points", "rowKey": "vendor_id", "enableSearch": true, "searchVariant": "typeahead", "searchOptionsField": "vendor_name", "searchFields": ["vendor_name", "vendor_id"], "emptyText": "No frontier calculations available.", "columns": [{"id": "vendor", "header": "Vendor", "cell": {"kind": "twoLine", "primary": "{{row.vendor_name}}", "secondary": "{{row.vendor_id}}"}}, {"id": "cost", "header": "Annual Spend ($)", "cell": {"kind": "number", "value": "{{row.annual_cost}}"}, "align": "right"}, {"id": "quality", "header": "Composite Quality Index", "cell": {"kind": "number", "value": "{{row.quality_index}}"}, "align": "right"}, {"id": "cost_per_pt", "header": "Cost per Quality Point ($)", "cell": {"kind": "number", "value": "{{row.cost_per_quality_point}}"}, "align": "right"}, {"id": "on_frontier", "header": "Frontier Status", "cell": {"kind": "chip", "value": "{{row.is_on_frontier}}", "colorMap": {"true": "success", "false": "error", "Optimal": "success", "Suboptimal": "error"}}}, {"id": "actions", "header": "Actions", "cell": {"kind": "actions", "buttons": [{"label": "Edit Spend", "icon": "edit", "variant": "outlined", "color": "primary", "onClick": [{"kind": "runOperation", "operation": "mdmScoring.updateSpend", "form": {"title": "Edit Annual Vendor Spend", "fields": [{"name": "annual_cost", "label": "Annual Spend ($)", "kind": "number", "step": 10000, "required": true}]}, "params": {"vendor_id": "{{row.vendor_id}}", "annual_cost": "{{form.annual_cost}}"}, "successMessage": "Annual spend updated for {{row.vendor_name}}."}]}]}}]}}, "entity_breakdown_hdr": {"id": "entity_breakdown_hdr", "type": "TextBlock", "props": {"text": "Domain / Entity Breakdown: Vendor Strengths by Data Category", "variant": "h6"}}, "entity_breakdown_desc": {"id": "entity_breakdown_desc", "type": "TextBlock", "props": {"text": "Vendors specialize in specific domains (e.g. S&P in ratings, Bloomberg in pricing, Refinitiv in party hierarchy). Compare non-aggregated standing per entity domain.", "variant": "body2", "color": "text.secondary"}}, "entity_breakdown_grid": {"id": "entity_breakdown_grid", "type": "DataGrid", "props": {"query": "scorecard", "rowsPath": "entity_breakdowns", "rowKey": "vendor_id,entity_domain", "enableSearch": true, "searchVariant": "typeahead", "searchOptionsField": "entity_domain", "searchFields": ["vendor_name", "vendor_id", "entity_domain"], "emptyText": "No entity breakdown data available.", "columns": [{"id": "vendor", "header": "Vendor", "cell": {"kind": "twoLine", "primary": "{{row.vendor_name}}", "secondary": "{{row.vendor_id}}"}}, {"id": "domain", "header": "Entity Domain", "cell": {"kind": "chip", "value": "{{row.entity_domain}}", "colorMap": {"security": "primary", "ratings": "warning", "benchmarks": "secondary", "pricing": "info", "party": "default"}}}, {"id": "attrs", "header": "Attributes", "cell": {"kind": "number", "value": "{{row.attribute_count}}"}, "align": "right"}, {"id": "cov", "header": "Coverage", "cell": {"kind": "percent", "value": "{{row.coverage_pct}}"}, "align": "right"}, {"id": "suff", "header": "Sufficiency", "cell": {"kind": "percent", "value": "{{row.sufficiency_rate_pct}}"}, "align": "right"}, {"id": "qual", "header": "Domain Quality", "cell": {"kind": "number", "value": "{{row.quality_index}}"}, "align": "right"}, {"id": "cost", "header": "Allocated Spend ($)", "cell": {"kind": "number", "value": "{{row.annual_cost}}"}, "align": "right"}, {"id": "cpp", "header": "Cost / Pt ($)", "cell": {"kind": "number", "value": "{{row.cost_per_quality_point}}"}, "align": "right"}, {"id": "frontier", "header": "Frontier Status", "cell": {"kind": "chip", "value": "{{row.is_on_frontier}}", "colorMap": {"true": "success", "false": "error", "Optimal": "success", "Suboptimal": "error"}}}, {"id": "actions", "header": "Actions", "cell": {"kind": "actions", "buttons": [{"label": "Edit Domain Spend", "icon": "edit", "variant": "outlined", "color": "primary", "onClick": [{"kind": "runOperation", "operation": "mdmScoring.updateSpend", "form": {"title": "Edit Domain Spend", "fields": [{"name": "annual_cost", "label": "Domain Spend ($)", "kind": "number", "step": 5000, "required": true}]}, "params": {"vendor_id": "{{row.vendor_id}}", "entity_domain": "{{row.entity_domain}}", "annual_cost": "{{form.annual_cost}}"}, "successMessage": "Domain spend updated for {{row.vendor_name}} ({{row.entity_domain}})."}]}]}}]}}, "candidate_select": {"id": "candidate_select", "type": "VariableSelect", "props": {"variable": "candidate_vendor", "label": "Candidate for Removal", "minWidth": 220, "options": [{"value": "BBG", "label": "Bloomberg ($2,140,000/yr)"}, {"value": "RFT", "label": "Refinitiv ($1,180,000/yr)"}, {"value": "FDS", "label": "FactSet ($720,000/yr)"}, {"value": "ICE", "label": "ICE Data ($540,000/yr)"}, {"value": "SPG", "label": "S&P Global ($610,000/yr)"}]}, "style": {"flex": "0 0 auto"}}, "displacement_kpis": {"id": "displacement_kpis", "type": "DataGrid", "props": {"query": "displacement", "rowsPath": "tier_summaries", "rowKey": "tier", "enableSearch": true, "searchVariant": "typeahead", "searchFields": ["tier"], "emptyText": "Select a candidate vendor to simulate removal.", "columns": [{"id": "tier", "header": "Attribute Tier", "cell": {"kind": "chip", "value": "{{row.tier}}", "colorMap": {"1": "warning", "2": "primary", "3": "default"}}}, {"id": "attrs", "header": "Attributes Count", "cell": {"kind": "number", "value": "{{row.attributes_count}}"}, "align": "right"}, {"id": "unchanged", "header": "Unchanged (Takeover Match)", "cell": {"kind": "percent", "value": "{{row.unchanged_pct}}"}, "align": "right"}, {"id": "changed", "header": "Changed (Within Tolerance)", "cell": {"kind": "percent", "value": "{{row.changed_pct}}"}, "align": "right"}, {"id": "now_null", "header": "Now NULL (Sole Source Lost)", "cell": {"kind": "percent", "value": "{{row.now_null_pct}}"}, "align": "right"}]}}, "residual_gaps_grid": {"id": "residual_gaps_grid", "type": "DataGrid", "props": {"query": "displacement", "rowsPath": "residual_gaps", "rowKey": "attribute_code", "enableSearch": true, "searchVariant": "typeahead", "searchOptionsField": "attribute_code", "searchFields": ["attribute_code"], "emptyText": "No residual gaps detected for this removal scenario.", "columns": [{"id": "attr", "header": "Attribute Code", "cell": {"kind": "text", "value": "{{row.attribute_code}}"}}, {"id": "tier", "header": "Tier", "cell": {"kind": "chip", "value": "{{row.tier}}", "colorMap": {"1": "warning", "2": "primary", "3": "default"}}}, {"id": "solo_rate", "header": "Solo Rate", "cell": {"kind": "percent", "value": "{{row.solo_rate_pct}}"}, "align": "right"}, {"id": "records_lost", "header": "Records Lost Without Replacement", "cell": {"kind": "number", "value": "{{row.records_lost}}"}, "align": "right"}]}}, "tolerances_grid": {"id": "tolerances_grid", "type": "DataGrid", "props": {"query": "tolerances", "emptyText": "No tolerances registered.", "enableSearch": true, "searchVariant": "typeahead", "searchOptionsField": "attribute_code", "searchFields": ["attribute_code", "match_type", "description"], "columns": [{"id": "code", "header": "Attribute Code", "cell": {"kind": "text", "value": "{{row.attribute_code}}"}}, {"id": "tier", "header": "Tier", "cell": {"kind": "chip", "value": "{{row.tier}}", "colorMap": {"1": "warning", "2": "primary", "3": "default"}}}, {"id": "match_type", "header": "Match Rule", "cell": {"kind": "text", "value": "{{row.match_type}}"}}, {"id": "tolerance", "header": "Tolerance Value", "cell": {"kind": "number", "value": "{{row.tolerance_val}}"}, "align": "right"}, {"id": "weight", "header": "Tier Weight", "cell": {"kind": "number", "value": "{{row.tier_weight}}"}, "align": "right"}, {"id": "desc", "header": "Description", "cell": {"kind": "text", "value": "{{row.description}}"}}]}}, "training_alert": {"id": "training_alert", "type": "AlertBanner", "props": {"severity": "info", "text": "User Training Guide: Learn how MDM Source Scoring evaluates market data feeds, eliminates vendor lock-in, and optimizes multi-million dollar data budgets."}}, "training_sec1": {"id": "training_sec1", "type": "TextBlock", "props": {"text": "1. What is Master Data Management (MDM) & Why Does This Page Exist?", "variant": "h6"}}, "training_text1": {"id": "training_text1", "type": "TextBlock", "props": {"text": "Financial institutions subscribe to multiple market data vendors (Bloomberg, Refinitiv, FactSet, ICE, S&P) costing upwards of $5M\u2013$20M annually. MDM continuously ingests all feeds, evaluates conflicting values against strict business rules, and crowns an authoritative \"Golden Record\" for each security and legal entity. This page gives data executives empirical metrics to challenge vendor contract renewals.", "variant": "body2"}}, "training_sec2": {"id": "training_sec2", "type": "TextBlock", "props": {"text": "2. Metric Definitions Cheat Sheet", "variant": "h6"}}, "training_text2": {"id": "training_text2", "type": "TextBlock", "props": {"text": "\u2022 Substitution Rate (SR): The percentage of entities where a secondary vendor matches the golden record within tolerance. High SR means the vendor can seamlessly replace the incumbent.\n\u2022 Coverage: The percentage of your portfolio universe that the vendor provides data for.\n\u2022 Solo Rate (Holdout Risk): The percentage of entities where this vendor is the ONLY source. High solo rates indicate high lock-in that will create NULLs if dropped.\n\u2022 Override Endorsement Rate (OER): How often human portfolio managers intervened to pick this vendor over other candidates.\n\u2022 Value-for-Money Frontier: Plots composite data quality against annual licensing cost to find Pareto-optimal vendors.", "variant": "body2"}}, "training_sec3": {"id": "training_sec3", "type": "TextBlock", "props": {"text": "3. Entity Domain Strengths & Spend Allocation", "variant": "h6"}}, "training_text3": {"id": "training_text3", "type": "TextBlock", "props": {"text": "Vendors are not equal across asset classes. In the Value for Money tab, examine the Domain Breakdown table:\n\u2022 Pricing: EOD prices and yields (Bloomberg & ICE excel).\n\u2022 Security Master: Instrument identifiers, ISINs, and shares (Bloomberg & Refinitiv).\n\u2022 Ratings: Credit ratings and sanctions flags (S&P Global excels with proprietary coverage).\n\u2022 Benchmarks: Index weights and industry sectors (FactSet & S&P Global).\n\u2022 Party / Legal Entity: LEIs, entity trees, and incorporation jurisdictions (Refinitiv PermID).\nClick \"Edit Spend\" on any vendor or domain row to simulate budget renegotiations in real time.", "variant": "body2"}}}$comp$::jsonb,
    $ds$[]$ds$::jsonb,
    $pe$[]$pe$::jsonb,
    $fb${"root": "filter_root", "nodes": {"filter_root": {"id": "filter_root", "type": "Column", "children": ["header_row", "pipeline_progress", "pipeline_hud"], "style": {"gap": "12px"}}, "header_row": {"id": "header_row", "type": "Row", "children": ["hdr", "universe_select", "entity_select", "vendor_filter", "sync_mart_btn", "run_pipeline_btn"], "style": {"alignItems": "center", "gap": "8px", "flexWrap": "wrap"}}}}$fb$::jsonb,
    $app${"chrome": "none", "surface": {"maxWidth": 1400, "padding": 3}, "tabVariable": "tab", "variables": [{"name": "universe_size", "default": "42000", "url": true}, {"name": "candidate_vendor", "default": "BBG", "url": true}, {"name": "vendor_filter", "default": "", "url": true}, {"name": "entity_domain", "default": "", "url": true}, {"name": "tier_filter", "default": "", "url": true}, {"name": "matrix_search", "default": "", "url": true}, {"name": "tab", "default": "matrix", "url": true}, {"name": "ingest_status", "default": null, "url": false}], "queries": [{"id": "scorecard", "operation": "mdmScoring.scorecard", "params": {"universe_size": "{{vars.universe_size}}", "entity_domain": "{{vars.entity_domain}}"}}, {"id": "tolerances", "operation": "mdmScoring.tolerances"}, {"id": "displacement", "operation": "mdmScoring.displacement", "params": {"dropped_vendor_id": "{{vars.candidate_vendor}}"}}]}$app$::jsonb,
    1,
